class Solution:
    def decode(self, encoded: List[int]) -> List[int]:
        n = len(encoded) + 1
        for first in range(1, n + 1):
            perm = [first]
            seen = [False] * (n + 1)
            seen[first] = True
            ok = True
            for e in encoded:
                nxt = perm[-1] ^ e
                if nxt < 1 or nxt > n or seen[nxt]:
                    ok = False
                    break
                seen[nxt] = True
                perm.append(nxt)
            if ok:
                return perm
        return []

