class Solution {
public:
    vector<int> decode(vector<int>& encoded) {
        int n = encoded.size() + 1;
        for (int first = 1; first <= n; ++first) {
            vector<int> perm{first};
            vector<char> seen(n + 1, false);
            seen[first] = true;
            bool ok = true;
            for (int e : encoded) {
                int nxt = perm.back() ^ e;
                if (nxt < 1 || nxt > n || seen[nxt]) { ok = false; break; }
                seen[nxt] = true;
                perm.push_back(nxt);
            }
            if (ok) return perm;
        }
        return {};
    }
};

