        int n = encoded.length + 1;
        for (int first = 1; first <= n; first++) {
            int[] perm = new int[n];
            boolean[] seen = new boolean[n + 1];
            perm[0] = first;
            seen[first] = true;
            boolean ok = true;
            for (int i = 0; i < encoded.length; i++) {
                perm[i + 1] = perm[i] ^ encoded[i];
                if (perm[i + 1] < 1 || perm[i + 1] > n || seen[perm[i + 1]]) { ok = false; break; }
                seen[perm[i + 1]] = true;
            }
            if (ok) return perm;
        }
        return new int[0];
    }
}

