class Solution {
public:
    vector<int> decode(vector<int>& encoded) {
        int n = encoded.size() + 1;
        int total = 0;
        for (int v = 1; v <= n; ++v)
            total ^= v;
        int oddSum = 0;
        for (int i = 1; i < (int)encoded.size(); i += 2)
            oddSum ^= encoded[i];
        vector<int> perm{total ^ oddSum};
        for (int e : encoded)
            perm.push_back(perm.back() ^ e);
        return perm;
    }
};

